 15	/**
 16	 * Socket服务器
 17	 * 处理客户端连接和命令请求
 18	 */
 19	public class SocketServer {
 20	 
 21	 private final int port;
 22	 private final CommandProcessor commandProcessor;
 23	 private ServerSocket serverSocket;
 24	 private ExecutorService executor;
 25	 private final AtomicBoolean running = new AtomicBoolean(false);
 26	 
 27	 public SocketServer(int port, CommandProcessor commandProcessor) {
 28	 this.port = port;
 29	 this.commandProcessor = commandProcessor;
 30	 this.executor = Executors.newCachedThreadPool(r -> {
 31	 Thread t = new Thread(r, "SocketServer-Worker");
 32	 t.setDaemon(true);
 33	 return t;
 34	 });
 35	 }
