 45	 public void createImageReader(int width, int height, int format, int maxImages) {
 46	 Ln.d("ImageReader creating: " + width + "x" + height + ", format=" + format + ", maxImages=" + maxImages);
 47	 // 清理之前的资源
 48	 close();
 49	 try {
 50	 // 创建ImageReader
 51	 imageReader = ImageReader.newInstance(width, height, format, maxImages);
 52	 // 创建后台线程处理图像回调
 53	 backgroundThread = new HandlerThread("ImageReaderHandler");
 54	 backgroundThread.start();
 55	 backgroundHandler = new Handler(backgroundThread.getLooper());
 56	 // 设置图像可用监听器
 57	 imageReader.setOnImageAvailableListener(new ImageReader.OnImageAvailableListener() {
 58	 @Override
 59	 public void onImageAvailable(ImageReader reader) {
 60	 handleImageAvailable(reader);
 61	 }
 62	 }, backgroundHandler);
 63	 Ln.i("ImageReader created successfully");
 64	 } catch (Exception e) {
 65	 Ln.e("Failed to create ImageReader", e);
 66	 close();
 67	 throw new RuntimeException("Failed to create ImageReader", e);
 68	 }
 69	 }
