 1	package com.github.kirer.adb.net;
 2	
 3	import com.genymobile.scrcpy.util.Ln;
 4	
 5	import java.util.HashMap;
 6	import java.util.Map;
 7	
 8	/**
 9	 * 命令处理器
 10	 * 负责注册、路由和执行各种服务命令
 11	 */
 12	public class CommandProcessor {
 13	 
 14	 private final Map<String, ServiceCommand> commands = new HashMap<>();
 15	 
 16	 /**
 17	 * 注册命令
 18	 */
 19	 public void registerCommand(ServiceCommand command) {
 20	 if (command == null) {
 21	 throw new IllegalArgumentException("Command cannot be null");
 22	 }
 23	 
 24	 String commandName = command.getCommandName().toLowerCase();
 25	 commands.put(commandName, command);
 26	 Ln.d("Registered command: " + commandName);
 27	 }
 28	 
 29	 /**
 30	 * 处理命令请求
 31	 */
 32	 public String processCommand(String request) {
 33	 if (request == null || request.trim().isEmpty()) {
 34	 return "ERROR Empty command";
 35	 }
 36	 
 37	 try {
 38	 String[] parts = request.trim().split("\\s+");
 39	 String commandName = parts[0].toLowerCase();
 40	 String[] params = new String[parts.length - 1];
 41	 System.arraycopy(parts, 1, params, 0, params.length);
 42	 
 43	 Ln.d("Processing command: " + commandName);
 44	 
 45	 // 内置命令
 46	 if ("help".equals(commandName)) {
 47	 return handleHelpCommand();
 48	 }
 49	 
 50	 if ("status".equals(commandName)) {
 51	 return "OK Service running with " + commands.size() + " commands";
 52	 }
 53	 
 54	 // 查找并执行注册的命令
 55	 ServiceCommand command = commands.get(commandName);
 56	 if (command == null) {
 57	 return "ERROR Unknown command: " + commandName;
 58	 }
 59	 
 60	 return command.execute(params);
 61	 
 62	 } catch (Exception e) {
 63	 Ln.e("Error processing command: " + request, e);
 64	 return "ERROR " + e.getMessage();
 65	 }
 66	 }
 67	 
 68	 private String handleHelpCommand() {
 69	 StringBuilder sb = new StringBuilder("Available commands:\n");
 70	 sb.append(" help - Show this help\n");
 71	 sb.append(" status - Show service status\n");
 72	 
 73	 for (ServiceCommand command : commands.values()) {
 74	 sb.append(" ").append(command.getCommandName())
 75	 .append(" - ").append(command.getHelp()).append("\n");
 76	 }
 77	 
 78	 return "OK " + sb.toString();
 79	 }
 80	}
