ccess() {\n return success;\n }\n \n /**\n * \u8f6c\u6362\u4e3a\u5b57\u7b26\u4e32\u683c\u5f0f\uff08\u7528\u4e8eSocket\u901a\u4fe1\uff09\n */\n public String toStringResponse() {\n if (success) {\n return \"OK \" + message;\n } else {\n return \"ERROR \" + message;\n }\n }\n \n @Override\n public String toString() {\n return \"CommandResult{\" +\n \"type=\" + type +\n \", success=\" + success +\n \", message='\" + message + '\\'' +\n \", hasData=\" + (data != null) +\n '}';\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在的 `ServiceCommand` 接口只支持返回字符串。我们有几种方式来支持返回 `Bitmap` 对象：

