{\n if (request == null || request.trim().isEmpty()) {\n return CommandResult.error(\"Empty command\");\n }\n \n try {\n String[] parts = request.trim().split(\"\\\\s+\");\n String commandName = parts[0].toLowerCase();\n String[] params = new String[parts.length - 1];\n System.arraycopy(parts, 1, params, 0, params.length);\n \n Ln.d(\"Processing command: \" + commandName);\n \n // \u5185\u7f6e\u547d\u4ee4\n if (\"help\".equals(commandName)) {\n return CommandResult.success(handleHelpCommand().substring(3)); // \u79fb\u9664 \"OK \" \u524d\u7f00\n }\n \n if (\"status\".equals(commandName)) {\n return CommandResult.success(\"Service running with \" + commands.size() + \" commands\");\n }\n \n // \u67e5\u627e\u5e76\u6267\u884c\u6ce8\u518c\u7684\u547d\u4ee4\n ServiceCommand command = commands.get(commandName);\n if (command == null) {\n return CommandResult.error(\"Unknown command: \" + commandName);\n }\n \n // \u5982\u679c\u662f\u6269\u5c55\u547d\u4ee4\uff0c\u4f7f\u7528\u6269\u5c55\u65b9\u6cd5\n if (command instanceof ExtendedServiceCommand) {\n return ((ExtendedServiceCommand) command).executeExtended(params);\n } else {\n // \u666e\u901a\u547d\u4ee4\uff0c\u5305\u88c5\u7ed3\u679c\n String result = command.execute(params);\n if (result.startsWith(\"OK \")) {\n return CommandResult.success(result.substring(3));\n } else if (result.startsWith(\"ERROR \")) {\n return CommandResult.error(result.substring(6));\n } else {\n return CommandResult.success(result);\n }\n }\n \n } catch (Exception e) {\n Ln.e(\"Error processing command: \" + request, e);\n return CommandResult.error(e.getMessage());\n }\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在添加一个方法来处理扩展命令并返回 `CommandResult`：
