h() + \"x\" + bitmap.getHeight());\n } else {\n Ln.w(\"Screenshot failed after \" + duration + \"ms\");\n }\n return bitmap;\n } catch (Exception e) {\n Ln.e(\"Error taking screenshot\", e);\n return null;\n }\n }", "old_str_start_line_number": 64, "old_str_end_line_number": 89, "new_str": " /**\n * \u83b7\u53d6\u5c4f\u5e55\u622a\u56fe\u7684\u516c\u5171\u63a5\u53e3\uff08\u540c\u6b65\u65b9\u6cd5\uff0c\u9632\u6b62\u5e76\u53d1\u95ee\u9898\uff09\n */\n public synchronized Bitmap takeScreenshot() {\n Ln.i(\"=== takeScreenshot() called ===\");\n Ln.i(\"Service state - running: \" + running + \", initialized: \" + initialized);\n \n if (!running || !initialized) {\n Ln.w(\"Service not running or not initialized - running: \" + running + \", initialized: \" + initialized);\n return null;\n }\n if (captureManager == null) {\n Ln.e(\"CaptureManager not available\");\n return null;\n }\n \n try {\n long startTime = System.currentTimeMillis();\n Ln.d(\"Starting screenshot capture...\");\n \n // \u76f4\u63a5\u83b7\u53d6\u622a\u56fe\uff0c\u4e0d\u91cd\u8bd5\n Bitmap bitmap = captureManager.captureScreen(3000); // 3\u79d2\u8d85\u65f6\n \n long duration = System.currentTimeMillis() - startTime;\n if (bitmap != null) {\n Ln.i(\"Screenshot taken successfully in \" + duration + \"ms, size: \" + bitmap.getWidth() + \"x\" + bitmap.getHeight());\n } else {\n Ln.w(\"Screenshot failed after \" + duration + \"ms - bitmap is null\");\n }\n return bitmap;\n } catch (Exception e) {\n Ln.e(\"Exception in takeScreenshot()\", e);\n return null;\n } finally {\n Ln.i(\"=== takeScreenshot() finished ===\");\n }\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"好主意！让我在关键位置添加详细的日志，然后通过 `adb logcat` 来查看服务挂掉的具体原因。

