itmap.getWidth() + \"x\" + bitmap.getHeight() : \"null\"));\n } else {\n Ln.w(\"No image available after waiting \" + timeoutMs + \"ms\");\n }\n } else {\n Ln.e(\"ImageReaderHandler is null!\");\n }\n \n // \u5904\u7406\u5c4f\u5e55\u65cb\u8f6c\n if (config.isAutoRotate() && displayInfo != null) {\n int rotationAngle = BitmapConverter.getRotationAngle(displayInfo.getRotation());\n if (rotationAngle != 0) {\n Ln.d(\"Rotating bitmap by \" + rotationAngle + \" degrees\");\n bitmap = BitmapConverter.rotateBitmap(bitmap, rotationAngle);\n }\n }\n \n Ln.i(\"Screen capture result: \" + (bitmap != null ? bitmap.getWidth() + \"x\" + bitmap.getHeight() : \"null\"));\n return bitmap;\n } catch (Exception e) {\n Ln.e(\"Exception in captureScreen()\", e);\n return null;\n } finally {\n if (image != null) {\n Ln.d(\"Closing image in finally block\");\n image.close();\n }\n Ln.i(\"=== captureScreen() finished ===\");\n }\n }", "old_str_start_line_number": 241, "old_str_end_line_number": 283, "new_str": " public Bitmap captureScreen(long timeoutMs) {\n try {\n Ln.d(\"Capturing screen...\");\n \n if (imageReaderHandler == null) {\n Ln.e(\"ImageReaderHandler is null!\");\n return null;\n }\n \n // \u76f4\u63a5\u83b7\u53d6\u6700\u65b0\u56fe\u50cf\uff0c\u4e0d\u4f7f\u7528\u7f13\u5b58\n Image image = imageReaderHandler.acquireLatestImage();\n if (image == null) {\n Ln.w(\"No image available from ImageReader\");\n return null;\n }\n \n try {\n Ln.d(\"Converting image to bitmap: \" + image.getWidth() + \"x\" + image.getHeight());\n Bitmap bitmap = BitmapConverter.imageToBitmap(image);\n \n // \u5904\u7406\u5c4f\u5e55\u65cb\u8f6c\n if (config.isAutoRotate() && displayInfo != null) {\n int rotationAngle = BitmapConverter.getRotationAngle(displayInfo.getRotation());\n if (rotationAngle != 0) {\n Ln.d(\"Rotating bitmap by \" + rotationAngle + \" degrees\");\n bitmap = BitmapConverter.rotateBitmap(bitmap, rotationAngle);\n }\n }\n \n Ln.d(\"Screen captured successfully: \" + (bitmap != null ? bitmap.getWidth() + \"x\" + bitmap.getHeight() : \"null\"));\n return bitmap;\n } finally {\n image.close();\n }\n \n } catch (Exception e) {\n Ln.e(\"Failed to capture screen\", e);\n return null;\n }\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"好的！让我简化整个截图逻辑，移除复杂的缓存和等待机制，每次都直接获取新的截图。

