 byte[] pngBytes = imageToBytes(image);\n if (pngBytes != null) {\n // \u7f13\u5b58\u5b57\u8282\u6570\u7ec4\n cachedPngBytes.set(pngBytes);\n Ln.d(\"ImageReaderHandler cached new PNG bytes: \" + pngBytes.length + \" bytes\");\n return pngBytes;\n }\n } else {\n Ln.d(\"ImageReader returned null on attempt \" + attempt);\n // \u77ed\u6682\u7b49\u5f85\u540e\u91cd\u8bd5\n if (attempt < 3) {\n try {\n Thread.sleep(50); // \u7b49\u5f8550ms\n } catch (InterruptedException e) {\n Thread.currentThread().interrupt();\n break;\n }\n }\n }\n } catch (Exception e) {\n Ln.w(\"Failed to acquire image on attempt \" + attempt, e);\n } finally {\n if (image != null) {\n image.close();\n }\n }\n }\n \n Ln.w(\"Failed to acquire any image after 3 attempts\");\n return null;\n }", "old_str_start_line_number": 113, "old_str_end_line_number": 161, "new_str": " /**\n * \u83b7\u53d6\u6700\u65b0\u7684PNG\u5b57\u8282\u6570\u7ec4\n */\n public byte[] getLatestPngBytes() {\n byte[] cached = cachedPngBytes.get();\n if (cached != null) {\n return cached;\n }\n \n if (imageReader == null) {\n Ln.e(\"ImageReader not available\");\n return null;\n }\n \n // \u5c1d\u8bd5\u83b7\u53d6\u65b0\u56fe\u50cf\u5e76\u8f6c\u6362\n return acquireAndConvertImage();\n }\n \n /**\n * \u83b7\u53d6\u56fe\u50cf\u5e76\u8f6c\u6362\u4e3aPNG\u5b57\u8282\u6570\u7ec4\n */\n private byte[] acquireAndConvertImage() {\n for (int attempt = 1; attempt <= 3; attempt++) {\n try (Image image = imageReader.acquireLatestImage()) {\n if (image != null) {\n byte[] pngBytes = imageToBytes(image);\n if (pngBytes != null) {\n cachedPngBytes.set(pngBytes);\n return pngBytes;\n }\n } else if (attempt < 3) {\n // \u77ed\u6682\u7b49\u5f85\u540e\u91cd\u8bd5\n try {\n Thread.sleep(50);\n } catch (InterruptedException e) {\n Thread.currentThread().interrupt();\n break;\n }\n }\n } catch (Exception e) {\n Ln.w(\"Failed to acquire image on attempt \" + attempt, e);\n }\n }\n return null;\n }"}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"typ