 33	 if (!screenshotService.isRunning()) {
 34	 return "ERROR Screenshot service is not running";
 35	 }
 36	
 37	 // 执行截图
 38	 boolean success = screenshotService.saveScreenshotSafe(outputPath);
 39	
 40	 if (success) {
 41	 return "OK Screenshot saved to " + outputPath;
 42	 } else {
 43	 return "ERROR Failed to capture or save screenshot";
 44	 }
 45	
 46	 } catch (Exception e) {
 47	 Ln.e("Error executing screenshot command", e);
 48	 return "ERROR " + e.getMessage();
 49	 }
 50	 }
