 9	 */
 10	public class BitmapCommand implements ServiceCommand {
 11	 private final ScreenshotService screenshotService;
 12	
 13	 public BitmapCommand(ScreenshotService screenshotService) {
 14	 this.screenshotService = screenshotService;
 15	 }
 16	
 17	 @Override
 18	 public String getName() {
 19	 return "bitmap";
 20	 }
 21	
 22	 @Override
 23	 public String execute(String[] params) {
 24	 try {
 25	 // 检查服务状态
 26	 if (!screenshotService.isRunning()) {
 27	 return "ERROR Screenshot service is not running";
 28	 }
 29	 
 30	 long startTime = System.currentTimeMillis();
 31	 
 32	 // 获取bitmap
 33	 Bitmap bitmap = screenshotService.takeScreenshot();
 34	 
 35	 long duration = System.currentTimeMillis() - startTime;
 36	 
 37	 if (bitmap != null) {
 38	 int width = bitmap.getWidth();
 39	 int height = bitmap.getHeight();
 40	 
 41	 // 回收bitmap
 42	 if (!bitmap.isRecycled()) {
 43	 bitmap.recycle();
 44	 }
 45	 
 46	 return "OK Bitmap captured in " + duration + "ms, size: " + width + "x" + height;
 47	 } else {
 48	 return "ERROR Failed to capture bitmap after " + duration + "ms";
 49	 }
 50	 
 51	 } catch (Exception e) {
 52	 Ln.e("Error executing bitmap command", e);
 53	 return "ERROR " + e.getMessage();
 54	 }
 55	 }
