 18	
 19	 private ImageReader imageReader;
 20	 private HandlerThread backgroundThread;
 21	 private Handler backgroundHandler;
 22	 private final ScreenshotConfig config;
 23	
 24	 // 缓存PNG字节数组而不是Image对象
 25	 private final AtomicReference<byte[]> cachedPngBytes = new AtomicReference<>();
 26	
 27	 /**
 28	 * 创建ImageReaderHandler实例
 29	 *
 30	 * @param config 截图配置
 31	 */
 32	 public ImageReaderHandler(ScreenshotConfig config) {
 33	 this.config = config;
 34	 }
