 36	 /**
 37	 * 创建ImageReader
 38	 *
 39	 * @param width 图像宽度
 40	 * @param height 图像高度
 41	 * @param format 图像格式
 42	 * @param maxImages 最大图像缓冲数量
 43	 */
 44	 public void createImageReader(int width, int height, int format, int maxImages) {
 45	 Ln.d("ImageReader creating: " + width + "x" + height + ", format=" + format + ", maxImages=" + maxImages);
 46	 // 清理之前的资源
 47	 close();
 48	 try {
 49	 // 创建ImageReader
 50	 imageReader = ImageReader.newInstance(width, height, format, maxImages);
 51	 // 创建后台线程处理图像回调
 52	 backgroundThread = new HandlerThread("ImageReaderHandler");
 53	 backgroundThread.start();
 54	 backgroundHandler = new Handler(backgroundThread.getLooper());
 55	 // 设置图像可用监听器
 56	 imageReader.setOnImageAvailableListener(new ImageReader.OnImageAvailableListener() {
 57	 @Override
 58	 public void onImageAvailable(ImageReader reader) {
