 134	 private byte[] imageToBytes(Image image) {
 135	 try {
 136	 // 获取Image的像素数据
 137	 Image.Plane[] planes = image.getPlanes();
 138	 if (planes.length == 0) {
 139	 Ln.e("Image has no planes");
 140	 return null;
 141	 }
 142	
 143	 Image.Plane plane = planes[0];
 144	 java.nio.ByteBuffer buffer = plane.getBuffer();
 145	
 146	 int width = image.getWidth();
 147	 int height = image.getHeight();
 148	 int pixelStride = plane.getPixelStride();
 149	 int rowStride = plane.getRowStride();
 150	 int rowPadding = rowStride - pixelStride * width;
 151	
 152	 // 创建Bitmap
 153	 android.graphics.Bitmap bitmap = android.graphics.Bitmap.createBitmap(
 154	 width + rowPadding / pixelStride, height, android.graphics.Bitmap.Config.ARGB_8888);
 155	 bitmap.copyPixelsFromBuffer(buffer);
 156	
 157	 // 如果有padding，需要裁剪
 158	 if (rowPadding != 0) {
 159	 bitmap = android.graphics.Bitmap.createBitmap(bitmap, 0, 0, width, height);
 160	 }
 161	
 162	 // 压缩为PNG
 163	 try (java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream()) {
 164	 bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, baos);
 165	 return baos.toByteArray();
 166	 } finally {
 167	 bitmap.recycle();
 168	 }
 169	
 170	 } catch (Exception e) {
 171	 Ln.e("Failed to convert image to bytes", e);
 172	 return null;
 173	 }
 174	 }
