 45	 return convertJPEGToBitmap(image);
 46	 case PixelFormat.RGBA_8888:
 47	 Ln.d("Converting RGBA8888 image to bitmap");
 48	 return convertRGBA8888ToBitmap(image);
 49	 default:
 50	 Ln.e("Unsupported image format: " + format);
 51	 return null;
 52	 }
 53	 } catch (Exception e) {
