 188	 private static void startSocketServer(ScreenshotService screenshotService) {
 189	 try {
 190	 // 创建命令处理器
 191	 CommandProcessor commandProcessor = new CommandProcessor();
 192	 // 注册命令
 193	 commandProcessor.registerCommand(new ScreenshotCommand(screenshotService));
