 195	 SocketServer socketServer = new SocketServer(socketPort, commandProcessor);
 196	 socketServer.start();
 197	 Ln.i("Socket server started on port " + socketPort);
 198	 } catch (Exception e) {
 199	 Ln.e("Failed to start socket server", e);
 200	 throw new RuntimeException("Socket server start failed", e);
 201	 }
 202	 }
