 210	 screenshotService = new ScreenshotService(config);
 211	 screenshotService.start();
 212	
 213	 // 创建命令处理器
 214	 CommandProcessor commandProcessor = new CommandProcessor();
 215	 commandProcessor.registerCommand(new ScreenshotCommand(screenshotService));
 216	
 217	 // 处理命令
 218	 CommandResult result;
 219	 if (command == null || command.trim().isEmpty()) {
 220	 // 如果没有提供命令，显示状态信息
 221	 result = CommandResult.success("Service initialized successfully. Available commands: screenshot [path], status, help");
 222	 } else {
 223	 // 执行指定的命令
 224	 result = commandProcessor.execute(command.trim());
 225	 }
