 167	 /**
 168	 * 开始屏幕捕获
 169	 *
 170	 * @throws Exception 启动失败时抛出异常
 171	 */
 172	 public void startCapture() throws Exception {
 173	 Ln.i("Starting screen capture...");
 174	 if (!initialized) {
 175	 throw new IllegalStateException("ScreenCaptureManager not initialized");
 176	 }
 177	 if (capturing) {
 178	 Ln.w("Screen capture already started");
 179	 return;
 180	 }
 181	 try {
 182	 // 创建ImageReader
 183	 int width = displayInfo.getSize().getWidth();
 184	 int height = displayInfo.getSize().getHeight();
 185	 imageReaderHandler.createImageReader(width, height);
 186	 // 创建VirtualDisplay
 187	 createVirtualDisplay();
 188	 capturing = true;
 189	 Ln.i("Screen capture started successfully");
 190	 } catch (Exception e) {
 191	 // 清理失败的资源
 192	 stopCapture();
 193	 throw e;
 194	 }
 195	 }
 196	
 197	 /**
 198	 * 停止屏幕捕获
 199	 */
 200	 public void stopCapture() {
 201	 Ln.i("Stopping screen capture...");
 202	
 203	 capturing = false;
 204	
 205	 // 释放VirtualDisplay
 206	 if (virtualDisplay != null) {
 207	 try {
 208	 virtualDisplay.release();
 209	 } catch (Exception e) {
 210	 Ln.w("Failed to release VirtualDisplay", e);
 211	 }
 212	 virtualDisplay = null;
 213	 }
 214	
 215	 // 关闭ImageReaderHandler
 216	 if (imageReaderHandler != null) {
 217	 imageReaderHandler.close();
 218	 }
 219	
 220	 Ln.i("Screen capture stopped");
 221	 }
