 238	 public Bitmap captureScreen(long timeoutMs) {
 239	 try {
 240	 if (imageReaderHandler == null) {
 241	 Ln.e("ImageReaderHandler is null");
 242	 return null;
 243	 }
 244	
 245	 byte[] imageBytes = imageReaderHandler.getLatestImageBytes();
 246	 if (imageBytes == null) {
 247	 return null;
 248	 }
 249	
 250	 android.graphics.Bitmap bitmap = android.graphics.BitmapFactory.decodeByteArray(imageBytes, 0, imageBytes.length);
 251	
 252	 if (bitmap != null && config.isAutoRotate() && displayInfo != null) {
 253	 int rotationAngle = BitmapConverter.getRotationAngle(displayInfo.getRotation());
 254	 if (rotationAngle != 0) {
 255	 bitmap = BitmapConverter.rotateBitmap(bitmap, rotationAngle);
 256	 }
 257	 }
