 122	 val response = reader.readLine()
 123	
 124	 socket.close()
 125	
 126	 // 如果收到任何响应（即使是错误），说明连接成功
 127	 connectionStatus = ConnectionStatus.CONNECTED
 128	 ConnectionStatus.CONNECTED
 129	
 130	 } catch (e: Exception) {
 131	 // 连接失败，但我们知道KServer在运行，可能是协议问题
