 292	 return connectionStatus
 293	 }
 294	
 295	 /**
 296	 * 从InputStream读取一行文本
 297	 */
 298	 private fun readLine(inputStream: InputStream): String? {
 299	 val buffer = StringBuilder()
 300	 var byte: Int
 301	 while (inputStream.read().also { byte = it } != -1) {
 302	 val char = byte.toChar()
 303	 if (char == '\n') {
 304	 break
 305	 } else if (char != '\r') {
 306	 buffer.append(char)
 307	 }
 308	 }
 309	 return if (buffer.isEmpty() && byte == -1) null else buffer.toString()
 310	 }
 311	}
