 145	 /**
 146	 * 获取指定区域的Bitmap
 147	 * @param x 起始X坐标
 148	 * @param y 起始Y坐标
 149	 * @param width 宽度（0表示使用图像宽度）
 150	 * @param height 高度（0表示使用图像高度）
 151	 * @return Bitmap对象
 152	 * @throws InterruptedException 中断异常
 153	 */
 154	 public static Bitmap getBitmap(int x, int y, int width, int height) throws InterruptedException {
 155	 while (true) {
 156	 synchronized (lock) {
 157	 if (buffer != null) {
 158	 // 创建缓冲区副本
 159	 ByteBuffer bufferCopy = ByteBuffer.allocate(buffer.capacity());
 160	 buffer.rewind();
 161	 bufferCopy.put(buffer);
 162	 bufferCopy.flip();
 163	
 164	 int currentBitmapWidth = bitmapWidth;
 165	 int currentHeight = ScreenShot.height;
 166	
 167	 // 创建Bitmap
 168	 Bitmap bitmap = Bitmap.createBitmap(currentBitmapWidth, currentHeight, Bitmap.Config.ARGB_8888);
 169	 bitmap.copyPixelsFromBuffer(bufferCopy);
 170	
 171	 // 处理裁剪参数
 172	 if (width == 0) {
 173	 width = bitmap.getWidth();
 174	 }
 175	 if (height == 0) {
 176	 height = bitmap.getHeight();
 177	 }
 178	
 179	 int cropWidth = width - x;
 180	 int cropHeight = height - y;
 181	
 182	 // 检查是否需要裁剪
 183	 if (cropWidth != bitmap.getWidth() || cropHeight != bitmap.getHeight()) {
 184	 return Bitmap.createBitmap(bitmap, x, y, cropWidth, cropHeight);
 185	 }
 186	 return bitmap;
 187	 }
 188	 }
 189	 sleep(20L);
 190	 }
 191	 }
