 196	 private static void recreateVirtualDisplay(int width, int height) {
 197	 if (imageReader != null) {
 198	 imageReader.close();
 199	 }
 200	
 201	 ImageReader newImageReader = ImageReader.newInstance(width, height, 1, 3);
 202	 imageReader = newImageReader;
 203	 imageReader.setOnImageAvailableListener(
 204	 imageReader1 -> processImage(imageReader1),
 205	 handler
 206	 );
 207	
 208	 SurfaceControl.openTransaction();
 209	 try {
 210	 IBinder displayToken = SurfaceControl.createDisplay("autogocap", false);
 211	 display = displayToken;
 212	 SurfaceControl.setDisplaySurface(displayToken, imageReader.getSurface());
 213	 SurfaceControl.setDisplayProjection(display, 0,
 214	 new Rect(0, 0, width, height),
 215	 new Rect(0, 0, width, height));
 216	 SurfaceControl.setDisplayLayerStack(display, 0);
 217	 } catch (Exception e) {
 218	 e.printStackTrace();
 219	 } finally {
 220	 SurfaceControl.closeTransaction();
 221	 }
 222	 }
