 172	 private fun buildStartCommand(apkPath: String, port: Int): String {
 173	 return """
 174	 # 停止现有进程
 175	 pkill -f 'com.github.kirer.adb.Launcher' || true
 176	 sleep 1
 177	
 178	 # 启动KServer Socket模式，使用APK作为CLASSPATH
 179	 # 使用nohup确保进程在后台持续运行
 180	 nohup sh -c "CLASSPATH='$apkPath' app_process /system/bin com.github.kirer.adb.Launcher -s -p $port" > /dev/null 2>&1 &
 181	
 182	 # 等待启动
 183	 sleep 3
 184	
 185	 # 检查进程是否启动
 186	 if pgrep -f 'com.github.kirer.adb.Launcher' > /dev/null; then
 187	 echo "KServer进程启动成功"
 188	 else
 189	 echo "KServer进程启动失败"
 190	 fi
 191	
 192	 # 检查端口是否监听
 193	 if netstat -an | grep ":$port.*LISTEN" > /dev/null; then
 194	 echo "Socket服务器监听端口${port}成功"
 195	 else
 196	 echo "Socket服务器监听端口${port}失败"
 197	 fi
 198	 """.trimIndent()
 199	 }
