 201	 /**
 202	 * 检查KServer进程是否运行
 203	 */
 204	 private suspend fun checkKServerProcess(shizukuManager: ShizukuManager): Boolean {
 205	 // 检查进程
 206	 val processResult = shizukuManager.executeShellCommand("pgrep -f 'com.github.kirer.adb.Launcher'")
 207	 val processRunning = processResult.success && processResult.output.trim().isNotEmpty()
 208	
 209	 // 检查端口监听
 210	 val portResult = shizukuManager.executeShellCommand("netstat -an | grep ':$DEFAULT_PORT.*LISTEN'")
 211	 val portListening = portResult.success && portResult.output.trim().isNotEmpty()
 212	
 213	 Log.d(TAG, "进程检查: 进程运行=$processRunning, 端口监听=$portListening")
 214	 Log.d(TAG, "进程输出: ${processResult.output}")
 215	 Log.d(TAG, "端口输出: ${portResult.output}")
 216	
 217	 // 如果进程存在但端口没有监听，说明进程僵死，需要重启
 218	 if (processRunning && !portListening) {
 219	 Log.w(TAG, "检测到僵死进程，尝试清理...")
 220	 cleanupZombieProcess(shizukuManager)
 221	 return false
 222	 }
 223	
 224	 return processRunning && portListening
 225	 }
