 15	/**
 16	 * Socket服务器
 17	 * 处理客户端连接和命令请求
 18	 */
 19	public class SocketServer {
 20	 
 21	 private final int port;
 22	 private final CommandProcessor commandProcessor;
 23	 private ServerSocket serverSocket;
 24	 private ExecutorService executor;
 25	 private final AtomicBoolean running = new AtomicBoolean(false);
 26	 
 27	 public SocketServer(int port, CommandProcessor commandProcessor) {
 28	 this.port = port;
 29	 this.commandProcessor = commandProcessor;
 30	 this.executor = Executors.newCachedThreadPool(r -> {
 31	 Thread t = new Thread(r, "SocketServer-Worker");
 32	 t.setDaemon(true);
 33	 return t;
 34	 });
 35	 }
 36	 
 37	 /**
 38	 * 启动服务器
 39	 */
 40	 public void start() throws IOException {
 41	 if (running.get()) {
 42	 Ln.w("Socket server already running");
 43	 return;
 44	 }
 45	 
 46	 serverSocket = new ServerSocket(port);
 47	 running.set(true);
 48	 
 49	 Ln.i("Socket server started on port " + port);
 50	 
 51	 // 启动接受连接的线程
 52	 Thread acceptThread = new Thread(this::acceptConnections, "SocketServer-Accept");
 53	 acceptThread.setDaemon(true);
 54	 acceptThread.start();
 55	 }
 56	 
 57	 /**
 58	 * 停止服务器
 59	 */
 60	 public void stop() {
 61	 if (!running.get()) {
 62	 return;
 63	 }
 64	 
 65	 running.set(false);
 66	 
 67	 try {
 68	 if (serverSocket != null && !serverSocket.isClosed()) {
 69	 serverSocket.close();
 70	 }
 71	 } catch (IOException e) {
 72	 Ln.w("Error closing server socket", e);
 73	 }
 74	 
 75	 if (executor != null) {
 76	 executor.shutdown();
 77	 }
 78	 
 79	 Ln.i("Socket server stopped");
 80	 }
 81	 
 82	 /**
 83	 * 接受客户端连接
 84	 */
 85	 private void acceptConnections() {
 86	 while (running.get()) {
 87	 try {
 88	 Socket clientSocket = serverSocket.accept();
 89	 executor.submit(() -> handleClient(clientSocket));
 90	 } catch (IOException e) {
 91	 if (running.get()) {
 92	 Ln.e("Error accepting client connection", e);
 93	 }
 94	 }
 95	 }
 96	 }
