 61	 log_info "编译DEX文件..."
 62	 if ./gradlew :server-adb-shell:buildDex; then
 63	 log_info "编译成功"
 64	 else
 65	 log_error "编译失败"
 66	 exit 1
 67	 fi
 68	}
