 81	# 启动Socket服务
 82	start_socket_service() {
 83	 log_info "启动Socket服务 (端口: $SOCKET_PORT)..."
 84	
 85	 # 清理日志
 86	 adb shell "rm -f $LOG_FILE" 2>/dev/null || true
 87	
 88	 # 启动服务
 89	 adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $SERVICE_CLASS --socket --port $SOCKET_PORT --debug > $LOG_FILE 2>&1 &"
 90	
 91	 # 等待启动
 92	 sleep 3
 93	
 94	 # 测试连接
 95	 log_info "测试服务连接..."
 96	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $TEST_CLASS localhost $SOCKET_PORT status" 2>/dev/null || echo "ERROR")
 97	
 98	 if [[ "$response" == *"OK"* ]]; then
 99	 log_info "✅ Socket服务启动成功！"
 100	 log_info "响应: $response"
 101	 else
 102	 log_error "❌ Socket服务启动失败"
 103	 log_info "查看日志:"
 104	 adb shell "cat $LOG_FILE 2>/dev/null || echo '无日志文件'"
 105	 exit 1
 106	 fi
 107	}
