 161	 echo " $0 -s -t screenshot <path> # Socket模式测试截图到路径（返回成功/失败）"
 162	 echo ""
 163	 echo "其他选项:"
 164	 echo " --no-build # 跳过编译"
 165	 echo " --stop # 停止Socket服务"
 166	 echo " --help # 显示帮助"
