 189	execute_direct_command() {
 190	 local command="$1"
 191	 if [ -z "$command" ]; then
 192	 log_error "直接命令不能为空"
 193	 exit 1
 194	 fi
 195	
 196	 log_info "执行直接命令: $command"
 197	
 198	 # 记录开始时间
 199	 local start_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 200	
 201	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $SERVICE_CLASS $command" 2>&1)
 202	
 203	 # 记录结束时间并计算耗时
 204	 local end_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 205	 local duration=$((end_time - start_time))
 206	
 207	 echo "$response"
 208	
 209	 # 如果是截图命令，显示耗时
 210	 if [[ "$command" == screenshot* ]]; then
 211	 log_info "⏱️ 命令执行耗时: ${duration}ms"
 212	 fi
 213	
 214	 if [[ "$response" == *"ERROR"* ]]; then
 215	 exit 1
 216	 else
 217	 exit 0
 218	 fi
 219	}
