 222	test_direct_screenshot() {
 223	 local screenshot_path="$1"
 224	
 225	 if [ -n "$screenshot_path" ]; then
 226	 log_info "直接模式截图到文件: $screenshot_path" >&2
 227	
 228	 # 记录总开始时间
 229	 local total_start_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 230	
 231	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $SERVICE_CLASS screenshot $screenshot_path" 2>&1)
 232	
 233	 # 记录总结束时间
 234	 local total_end_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 235	 local total_duration=$((total_end_time - total_start_time))
 236	
 237	 if [[ "$response" == *"OK"* ]]; then
 238	 log_info "✅ 直接模式截图成功" >&2
 239	 log_info "⏱️ 总耗时: ${total_duration}ms" >&2
 240	 echo "响应: $response" >&2
 241	 else
 242	 log_error "❌ 直接模式截图失败" >&2
 243	 echo "$response" >&2
 244	 exit 1
 245	 fi
 246	 else
 247	 log_info "直接模式获取bitmap（不保存文件）" >&2
 248	
 249	 # 记录开始时间
 250	 local start_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 251	
 252	 # 使用screenshot命令（无参数）来测试bitmap获取，将二进制数据丢弃，避免在终端显示乱码
 253	 adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $SERVICE_CLASS screenshot" > /dev/null
 254	 local exit_code=$?
 255	
 256	 # 记录结束时间
 257	 local end_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 258	 local total_duration=$((end_time - start_time))
 259	
 260	 if [ $exit_code -eq 0 ]; then
 261	 log_info "✅ 直接模式bitmap获取成功" >&2
 262	 log_info "⏱️ 总耗时: ${total_duration}ms" >&2
 263	 log_info " 提示: 二进制数据已生成但未显示（避免终端乱码）" >&2
 264	 else
 265	 log_error "❌ 直接模式bitmap获取失败" >&2
 266	 exit 1
 267	 fi
 268	 fi
 269	}
