 271	# Socket模式截图测试
 272	test_socket_screenshot() {
 273	 local screenshot_path="$1"
 274	
 275	 # 截图前先检查服务状态
 276	 log_info "检查服务状态..."
 277	 local status_response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $TEST_CLASS localhost $SOCKET_PORT 'status'" 2>/dev/null || echo "ERROR")
 278	
 279	 if [[ "$status_response" != *"OK"* ]]; then
 280	 log_error "❌ 服务状态异常，无法执行截图"
 281	 echo "状态响应: $status_response"
 282	 exit 1
 283	 fi
 284	
 285	 log_info "✅ 服务状态正常，开始截图..."
 286	
 287	 if [ -n "$screenshot_path" ]; then
 288	 log_info "Socket模式截图到文件: $screenshot_path"
 289	
 290	 # 记录总开始时间
 291	 local total_start_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 292	
 293	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $TEST_CLASS localhost $SOCKET_PORT 'screenshot $screenshot_path'" 2>/dev/null || echo "ERROR")
 294	
 295	 # 记录总结束时间
 296	 local total_end_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 297	 local total_duration=$((total_end_time - total_start_time))
 298	
 299	 if [[ "$response" == *"OK"* ]]; then
 300	 log_info "✅ Socket模式截图成功"
 301	 log_info "⏱️ Socket命令总耗时: ${total_duration}ms"
 302	 echo "响应: $response"
 303	 else
 304	 log_error "❌ Socket模式截图失败"
 305	 echo "$response"
 306	 exit 1
 307	 fi
 308	 else
 309	 log_info "Socket模式获取bitmap（不保存文件）"
 310	
 311	 # 记录开始时间
 312	 local start_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 313	
 314	 # 将二进制数据重定向到/dev/null，只保留stderr的响应信息
 315	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $TEST_CLASS localhost $SOCKET_PORT 'screenshot'" 2>&1 > /dev/null || echo "ERROR")
 316	
 317	 # 记录结束时间
 318	 local end_time=$(python3 -c "import time; print(int(time.time() * 1000))" 2>/dev/null || echo $(($(date +%s) * 1000)))
 319	 local total_duration=$((end_time - start_time))
 320	
 321	 if [[ "$response" == *"OK"* ]] || [[ "$response" == *"BYTES_SIZE"* ]]; then
 322	 log_info "✅ Socket模式bitmap获取成功"
 323	 log_info "⏱️ Socket通信总耗时: ${total_duration}ms"
 324	 log_info " 提示: 二进制数据已生成但未显示（避免终端乱码）"
 325	 echo "响应信息: $response"
 326	 else
 327	 log_error "❌ Socket模式bitmap获取失败"
 328	 echo "$response"
 329	 exit 1
 330	 fi
 331	 fi
 332	}
