 334	# 主函数
 335	main() {
 336	 local do_build=true
 337	 local mode="" # -d (direct) 或 -s (socket)
 338	 local test_mode=false # -t (test)
 339	 local screenshot_mode=false
 340	 local screenshot_path=""
 341	
 342	 # 解析参数
 343	 while [[ $# -gt 0 ]]; do
 344	 case $1 in
 345	 -d)
 346	 mode="direct"
 347	 shift
 348	 ;;
 349	 -s)
 350	 mode="socket"
 351	 shift
 352	 ;;
 353	 -t)
 354	 test_mode=true
 355	 shift
 356	 ;;
 357	 --screenshot|screenshot)
 358	 screenshot_mode=true
 359	 # 检查下一个参数是否是路径
 360	 if [[ $# -gt 1 && ! "$2" =~ ^- ]]; then
 361	 screenshot_path="$2"
 362	 shift 2
 363	 else
 364	 shift
 365	 fi
 366	 ;;
 367	 --no-build)
 368	 do_build=false
 369	 shift
 370	 ;;
 371	 --port)
 372	 SOCKET_PORT="$2"
 373	 shift 2
 374	 ;;
 375	 --stop)
 376	 stop_existing_service
 377	 log_info "Socket服务已停止"
 378	 exit 0
 379	 ;;
 380	 --help)
 381	 show_usage
 382	 exit 0
 383	 ;;
 384	 *)
 385	 log_warn "未知选项: $1"
 386	 shift
 387	 ;;
 388	 esac
 389	 done
 390	
 391	 # 验证参数组合
 392	 if [ -z "$mode" ]; then
 393	 log_error "必须指定模式: -d (直接模式) 或 -s (Socket模式)"
 394	 show_usage
 395	 exit 1
 396	 fi
 397	
 398	 if [ "$test_mode" = true ] && [ "$mode" != "socket" ]; then
 399	 log_error "-t (测试模式) 只能与 -s (Socket模式) 一起使用"
 400	 exit 1
 401	 fi
 402	
 403	 log_info "=== KServer 快速部署 ==="
 404	
 405	 # 检查设备
 406	 check_device
 407	
 408	 # 根据模式执行相应操作
 409	 if [ "$mode" = "direct" ]; then
 410	 # 直接模式 - 所有日志输出到stderr
 411	 log_info "直接模式部署" >&2
 412	
 413	 # 停止现有服务
 414	 stop_existing_service >&2
 415	
 416	 # 编译
 417	 if [ "$do_build" = true ]; then
 418	 build_dex >&2
 419	 fi
 420	
 421	 # 部署
 422	 deploy >&2
 423	
 424	 # 如果有截图需求，执行截图测试
 425	 if [ "$screenshot_mode" = true ]; then
 426	 test_direct_screenshot "$screenshot_path"
 427	 else
 428	 log_info "✅ 直接模式部署完成" >&2
 429	 fi
 430	
 431	 elif [ "$mode" = "socket" ]; then
 432	 # Socket模式
 433	 if [ "$test_mode" = true ]; then
 434	 # 测试模式
 435	 log_info "Socket模式测试"
 436	
 437	 if [ "$screenshot_mode" = true ]; then
 438	 test_socket_screenshot "$screenshot_path"
 439	 else
 440	 test_socket_service
 441	 fi
 442	 else
 443	 # 部署模式
 444	 log_info "Socket模式部署"
 445	
 446	 # 停止现有服务
 447	 stop_existing_service
 448	
 449	 # 编译
 450	 if [ "$do_build" = true ]; then
 451	 build_dex
 452	 fi
 453	
 454	 # 部署
 455	 deploy
 456	
 457	 # 启动Socket服务
 458	 start_socket_service
 459	
 460	 # 如果有截图需求，执行截图测试
 461	 if [ "$screenshot_mode" = true ]; then
 462	 echo ""
 463	 test_socket_screenshot "$screenshot_path"
 464	 else
 465	 echo ""
 466	 log_info " Socket模式部署完成！"
 467	 log_info ""
 468	 log_info "测试命令:"
 469	 echo " $0 -s -t --screenshot # 测试bitmap字节数组获取（不显示数据）"
 470	 echo " $0 -s -t --screenshot <path> # 测试截图到文件"
 471	 fi
 472	 fi
 473	 fi
 474	}
 475	
 476	# 执行主函数
 477	main "$@"
