 61	 displayInfo = displayManager.getDisplayInfo(displayId);
 62	 if (displayInfo == null) {
 63	 throw new Exception("Display " + displayId + " not found");
 64	 }
 65	 Ln.i("Display info: " + displayInfo.getSize().getWidth() + "x" + displayInfo.getSize().getHeight() + ", rotation=" + displayInfo.getRotation() + ", dpi=" + displayInfo.getDpi());
 66	 // 创建ImageReaderHandler
 67	 imageReaderHandler = new ImageReaderHandler(config);
 68	 initialized = true;
