 145	 private static void setDisplaySurface(IBinder display, Surface surface, Rect deviceRect, Rect displayRect, int layerStack) {
 146	 SurfaceControl.openTransaction();
 147	 try {
 148	 SurfaceControl.setDisplaySurface(display, surface);
 149	 SurfaceControl.setDisplayProjection(display, 0, deviceRect, displayRect);
 150	 SurfaceControl.setDisplayLayerStack(display, layerStack);
 151	 } finally {
 152	 SurfaceControl.closeTransaction();
