 296	 public void setOutputFormat(OptimizedImageProcessor.OutputFormat format, int quality) {
 297	 if (imageReaderHandler == null) {
 298	 Ln.w("ImageReaderHandler is null, cannot set output format");
 299	 return;
 300	 }
 301	
 302	 OptimizedImageProcessor.CompressionConfig config;
 303	 switch (format) {
 304	 case RAW_RGBA:
 305	 config = OptimizedImageProcessor.CompressionConfig.rawRgba();
 306	 break;
 307	 case PNG:
 308	 config = OptimizedImageProcessor.CompressionConfig.png();
 309	 break;
 310	 case JPEG:
 311	 config = OptimizedImageProcessor.CompressionConfig.jpeg(quality);
 312	 break;
 313	 case WEBP:
 314	 config = OptimizedImageProcessor.CompressionConfig.webp(quality);
 315	 break;
 316	 default:
 317	 Ln.w("Unsupported output format: " + format);
 318	 return;
 319	 }
 320	
 321	 imageReaderHandler.setCompressionConfig(config);
 322	 Ln.i("Output format set to: " + format + (quality < 100 ? ", quality=" + quality : ""));
 323	 }
