e55\u5206\u8fa8\u7387: ${width}x${height}, \u671f\u671b\u6570\u636e\u5927\u5c0f: $expectedSize, \u5b9e\u9645\u6570\u636e\u5927\u5c0f: ${data.size}\")\n \n if (data.size == expectedSize) {\n // \u521b\u5efaBitmap\u5e76\u8bbe\u7f6e\u50cf\u7d20\u6570\u636e\n val bitmap = android.graphics.Bitmap.createBitmap(width, height, android.graphics.Bitmap.Config.ARGB_8888)\n val buffer = java.nio.ByteBuffer.wrap(data)\n bitmap.copyPixelsFromBuffer(buffer)\n \n binding.ivScreenshot.setImageBitmap(bitmap)\n \n val sizeText = formatFileSize(size)\n binding.tvImageInfo.text = \"\u683c\u5f0f: $format, \u5927\u5c0f: $sizeText, \u5206\u8fa8\u7387: ${width}x${height}\"\n \n addLog(\"RAW\u622a\u56fe\u663e\u793a\u6210\u529f: ${width}x${height}, $sizeText\")\n } else {\n // \u5c1d\u8bd5\u6839\u636e\u6570\u636e\u5927\u5c0f\u63a8\u7b97\u5206\u8fa8\u7387\n val pixelCount = data.size / 4 // RGBA = 4 bytes per pixel\n addLog(\"RAW\u6570\u636e\u5927\u5c0f\u4e0d\u5339\u914d\uff0c\u671f\u671b: $expectedSize, \u5b9e\u9645: ${data.size}\")\n addLog(\"\u6570\u636e\u5305\u542b $pixelCount \u4e2a\u50cf\u7d20\")\n \n // \u5c1d\u8bd5\u5e38\u89c1\u7684\u5206\u8fa8\u7387\u6bd4\u4f8b\n val possibleResolutions = listOf(\n Pair(1080, 2400), Pair(1080, 2340), Pair(1080, 1920),\n Pair(1440, 3200), Pair(1440, 2960), Pair(1440, 2560),\n Pair(720, 1600), Pair(720, 1280)\n )\n \n for ((w, h) in possibleResolutions) {\n if (w * h * 4 == data.size) {\n addLog(\"\u63a8\u6d4b\u5206\u8fa8\u7387: ${w}x${h}\")\n val bitmap = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)\n val buffer = java.nio.ByteBuffer.wrap(data)\n bitmap.copyPixelsFromBuffer(buffer)\n \n binding.ivScreenshot.setImageBitmap(bitmap)\n \n val sizeText = formatFileSize(size)\n binding.tvImageInfo.text = \"\u683c\u5f0f: $format, \u5927\u5c0f: $sizeText, \u5206\u8fa8\u7387: ${w}x${h} (\u63a8\u6d4b)\"\n \n addLog(\"RAW\u622a\u56fe\u663e\u793a\u6210\u529f(\u63a8\u6d4b\u5206\u8fa8\u7387): ${w}x${h}, $sizeText\")\n return\n }\n }\n \n addLog(\"\u65e0\u6cd5\u786e\u5b9aRAW\u6570\u636e\u7684\u5206\u8fa8\u7387\")\n }", "old_str_start_line_number": 426, "old_str_end_line_number": 446}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"找到了！问题在第430-431行，我们硬编码了分辨率。让我修复这个问题，动态获取屏幕分辨率：
