l sizeText = formatFileSize(size)\n binding.tvImageInfo.text = \"\u683c\u5f0f: $format, \u5927\u5c0f: $sizeText, \u5206\u8fa8\u7387: ${guessWidth}x${guessHeight} (\u5f3a\u5236\u663e\u793a)\"\n \n addLog(\"\u5f3a\u5236\u663e\u793a\u6210\u529f: ${guessWidth}x${guessHeight}\")\n } catch (e: Exception) {\n addLog(\"\u5f3a\u5236\u663e\u793a\u5931\u8d25: ${e.message}\")\n }\n }\n }", "old_str_start_line_number": 485, "old_str_end_line_number": 485}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在添加更详细的调试信息：
