 447	 private fun formatFileSize(bytes: Int): String {
 448	 return when {
 449	 bytes < 1024 -> "$bytes B"
 450	 bytes < 1024 * 1024 -> "${bytes / 1024} KB"
 451	 else -> "${bytes / (1024 * 1024)} MB"
 452	 }
 453	 }
