 10	/**
 11	 * 截图命令实现 - 支持保存文件和返回bitmap字节数组
 12	 */
 13	public class ScreenshotCommand implements ServiceCommand {
 14	
 15	 private final ScreenshotService screenshotService;
 16	
 17	 public ScreenshotCommand(ScreenshotService screenshotService) {
 18	 this.screenshotService = screenshotService;
 19	 }
 20	
 21	 @Override
 22	 public CommandResult execute(String[] params) {
 23	 try {
 24	 // 检查服务状态
 25	 if (!screenshotService.isRunning()) {
 26	 return CommandResult.error("Screenshot service is not running");
 27	 }
 28	 if (params.length == 0) {
 29	 // 无参数：返回bitmap字节数组
 30	 return getBitmapResult();
 31	 }
 32	 // 有参数：保存到文件
 33	 String outputPath = params[0];
 34	 // 验证路径
 35	 if (outputPath.trim().isEmpty()) {
 36	 return CommandResult.error("Invalid output path");
 37	 }
 38	 return saveBitmapResult(outputPath);
 39	 } catch (Exception e) {
 40	 Ln.e("Error executing screenshot command", e);
 41	 return CommandResult.error(e.getMessage());
 42	 }
 43	 }
 44	
 45	 /**
 46	 * 获取PNG字节数组结果
 47	 */
 48	 private CommandResult getBitmapResult() {
 49	 long startTime = System.currentTimeMillis();
 50	 byte[] bytes = screenshotService.getLatestImageBytes();
 51	 long duration = System.currentTimeMillis() - startTime;
 52	 if (bytes != null) {
 53	 String message = "PNG bytes captured in " + duration + "ms, bytes: " + bytes.length;
 54	 return CommandResult.bytes(bytes, message);
 55	 } else {
 56	 return CommandResult.error("Failed to capture PNG bytes after " + duration + "ms");
 57	 }
 58	 }
 59	
 60	 /**
 61	 * 保存到文件并返回布尔结果
 62	 */
 63	 private CommandResult saveBitmapResult(String outputPath) {
 64	 byte[] bytes = screenshotService.getLatestImageBytes();
 65	 if (bytes == null) {
 66	 return CommandResult.bool(false, "Failed to capture PNG bytes");
 67	 }
 68	 try (FileOutputStream fos = new FileOutputStream(outputPath)) {
 69	 fos.write(bytes);
 70	 fos.flush();
 71	 String message = "Screenshot saved to " + outputPath + " (" + bytes.length + " bytes)";
 72	 return CommandResult.bool(true, message);
 73	 } catch (Exception e) {
 74	 Ln.e("Failed to save screenshot", e);
 75	 return CommandResult.bool(false, "Failed to save screenshot: " + e.getMessage());
 76	 }
 77	 }
 78	
 79	 @Override
 80	 public String getCommandName() {
 81	 return "screenshot";
 82	 }
 83	
 84	 @Override
 85	 public String getHelp() {
 86	 return "Take a screenshot. Usage: screenshot [output_path] - with path: save to file, without path: return bitmap data";
 87	 }
 88	}
