 186	 imageProcessor.processImage(image, compressionConfig);
 187	 if (newResult != null) {
 188	 // 更新缓存
 189	 OptimizedImageProcessor.ProcessResult oldResult = cachedResult.getAndSet(newResult);
 190	 if (oldResult != null) {
 191	 imageProcessor.releaseResult(oldResult);
 192	 }
 193	 return AshmemManager.readFromBuffer(newResult.buffer, newResult.dataSize);
 194	 }
 195	 }
 196	 } catch (Exception e) {
 197	 Ln.w("Failed to acquire image", e);
 198	 }
 199	 } else {
 200	 // 降级模式
 201	 Ln.d("使用降级模式获取图像数据");
 202	 return getLatestPngBytes();
 203	 }
 204	 return null;
 205	 }
