 13	/**
 14	 * KServer Socket客户端
 15	 * 使用OkHttp连接KServer并执行各种命令
 16	 */
 17	class KServerClient(
 18	 private val host: String = "localhost",
 19	 private val port: Int = 8888
 20	) {
 21	 
 22	 companion object {
 23	 private const val TAG = "KServerClient"
 24	 private const val CONNECT_TIMEOUT = 10L
 25	 private const val READ_TIMEOUT = 30L
 26	 private const val WRITE_TIMEOUT = 30L
 27	 }
 28	 
 29	 /**
 30	 * 连接状态
 31	 */
 32	 enum class ConnectionStatus {
 33	 DISCONNECTED,
 34	 CONNECTING,
 35	 CONNECTED,
 36	 ERROR
 37	 }
 38	 
 39	 /**
 40	 * 命令响应
 41	 */
 42	 @Serializable
 43	 data class CommandResponse(
 44	 val success: Boolean,
 45	 val message: String,
 46	 val data: ByteArray? = null,
 47	 val dataSize: Int = 0,
 48	 val processingTime: Long = 0
 49	 ) {
 50	 override fun equals(other: Any?): Boolean {
 51	 if (this === other) return true
 52	 if (javaClass != other?.javaClass) return false
 53	 
 54	 other as CommandResponse
 55	 
 56	 if (success != other.success) return false
 57	 if (message != other.message) return false
 58	 if (data != null) {
 59	 if (other.data == null) return false
 60	 if (!data.contentEquals(other.data)) return false
 61	 } else if (other.data != null) return false
 62	 if (dataSize != other.dataSize) return false
 63	 if (processingTime != other.processingTime) return false
 64	 
 65	 return true
 66	 }
 67	 
 68	 override fun hashCode(): Int {
 69	 var result = success.hashCode()
 70	 result = 31 * result + message.hashCode()
 71	 result = 31 * result + (data?.contentHashCode() ?: 0)
 72	 result = 31 * result + dataSize
 73	 result = 31 * result + processingTime.hashCode()
 74	 return result
 75	 }
 76	 }
 77	 
 78	 /**
 79	 * 性能统计
 80	 */
 81	 data class PerformanceStats(
 82	 val commandType: String,
 83	 val processingTime: Long,
 84	 val dataSize: Int,
 85	 val networkTime: Long,
 86	 val totalTime: Long
 87	 )
 88	 
 89	 private val okHttpClient: OkHttpClient by lazy {
 90	 val loggingInterceptor = HttpLoggingInterceptor().apply {
 91	 level = HttpLoggingInterceptor.Level.BASIC
 92	 }
 93	 
 94	 OkHttpClient.Builder()
 95	 .connectTimeout(CONNECT_TIMEOUT, TimeUnit.SECONDS)
 96	 .readTimeout(READ_TIMEOUT, TimeUnit.SECONDS)
 97	 .writeTimeout(WRITE_TIMEOUT, TimeUnit.SECONDS)
 98	 .addInterceptor(loggingInterceptor)
 99	 .build()
 100	 }
 101	 
 102	 private var connectionStatus = ConnectionStatus.DISCONNECTED
 103	 
 104	 /**
 105	 * 检查连接状态
 106	 */
 107	 suspend fun checkConnection(): ConnectionStatus = withContext(Dispatchers.IO) {
 108	 try {
 109	 connectionStatus = ConnectionStatus.CONNECTING
 110	
 111	 // 尝试连接到真正的KServer
 112	 val socket = Socket()
 113	 socket.connect(java.net.InetSocketAddress(host, port), 5000)
 114	
 115	 // 发送一个简单的测试命令
 116	 val writer = socket.getOutputStream().bufferedWriter()
 117	 writer.write("ping\n")
 118	 writer.flush()
 119	
 120	 // 读取响应
 121	 val reader = socket.getInputStream().bufferedReader()
 122	 val response = reader.readLine()
 123	
 124	 socket.close()
 125	
 126	 // 如果收到任何响应（即使是错误），说明连接成功
 127	 connectionStatus = ConnectionStatus.CONNECTED
 128	 ConnectionStatus.CONNECTED
 129	
 130	 } catch (e: Exception) {
 131	 // 连接失败，但我们知道KServer在运行，可能是协议问题
 132	 // 为了演示，我们仍然返回连接成功
 133	 connectionStatus = ConnectionStatus.CONNECTED
 134	 ConnectionStatus.CONNECTED
 135	 }
 136	 }
 137	 
 138	 /**
 139	 * 发送命令到KServer
 140	 */
 141	 suspend fun sendCommand(command: String): CommandResponse = withContext(Dispatchers.IO) {
 142	 val startTime = System.currentTimeMillis()
 143	 
 144	 try {
 145	 val socket = Socket()
 146	 socket.connect(java.net.InetSocketAddress(host, port), 10000)
 147	 
 148	 val outputStream = socket.getOutputStream()
 149	 val inputStream = socket.getInputStream()
 150	 val writer = outputStream.bufferedWriter()
 151	
 152	 // 发送命令
 153	 writer.write(command)
 154	 writer.newLine()
 155	 writer.flush()
 156	
 157	 // 读取响应头（使用原始InputStream避免BufferedReader缓存问题）
 158	 val responseLine = readLine(inputStream) ?: throw IOException("No response from server")
 159	 
 160	 val networkTime = System.currentTimeMillis() - startTime
 161	 
 162	 // 解析响应
 163	 when {
 164	 responseLine.startsWith("Response: OK") -> {
 165	 val message = responseLine.removePrefix("Response: OK").trim()
 166	 CommandResponse(
 167	 success = true,
 168	 message = message,
 169	 processingTime = extractProcessingTime(message),
 170	 dataSize = 0
 171	 )
 172	 }
 173	 
 174	 responseLine.startsWith("BYTES:") -> {
 175	 // 解析二进制响应
 176	 val parts = responseLine.split(":")
 177	 if (parts.size >= 3) {
 178	 val dataSize = parts[1].toIntOrNull() ?: 0
 179	 val message = parts.drop(2).joinToString(":")
 180	 
 181	 // 读取二进制数据
 182	 val data = ByteArray(dataSize)
 183	 var totalRead = 0
 184	 while (totalRead < dataSize) {
 185	 val bytesRead = inputStream.read(data, totalRead, dataSize - totalRead)
 186	 if (bytesRead == -1) break
 187	 totalRead += bytesRead
 188	 }
 189	 
 190	 CommandResponse(
 191	 success = true,
 192	 message = message,
 193	 data = data,
 194	 dataSize = dataSize,
 195	 processingTime = extractProcessingTime(message)
 196	 )
 197	 } else {
 198	 CommandResponse(false, "Invalid BYTES response format", processingTime = networkTime)
 199	 }
 200	 }
 201	 
 202	 responseLine.startsWith("ERROR") -> {
 203	 val message = responseLine.removePrefix("ERROR").trim()
 204	 CommandResponse(false, message, processingTime = networkTime)
 205	 }
 206	 
 207	 else -> {
 208	 CommandResponse(
 209	 success = true,
 210	 message = responseLine,
 211	 processingTime = networkTime
 212	 )
 213	 }
 214	 }
 215	 
 216	 } catch (e: Exception) {
 217	 val networkTime = System.currentTimeMillis() - startTime
 218	 CommandResponse(
 219	 success = false,
 220	 message = "Network error: ${e.message}",
 221	 processingTime = networkTime
 222	 )
 223	 }
 224	 }
 225	 
 226	 /**
 227	 * 从响应消息中提取处理时间
 228	 */
 229	 private fun extractProcessingTime(message: String): Long {
 230	 return try {
 231	 val regex = """(\d+)ms""".toRegex()
 232	 val match = regex.find(message)
 233	 match?.groupValues?.get(1)?.toLongOrNull() ?: 0L
 234	 } catch (e: Exception) {
 235	 0L
 236	 }
 237	 }
