 169	 /**
 170	 * 构建启动命令
 171	 */
 172	 private fun buildStartCommand(apkPath: String, port: Int): String {
 173	 return """
 174	 # 停止现有进程
 175	 pkill -f 'com.github.kirer.adb.Launcher' || true
 176	 sleep 1
 177	
 178	 # 启动KServer Socket模式，使用APK作为CLASSPATH
 179	 # 使用nohup确保进程在后台持续运行
 180	 nohup sh -c "CLASSPATH='$apkPath' app_process /system/bin com.github.kirer.adb.Launcher -s -p $port" > /dev/null 2>&1 &
 181	
 182	 # 等待启动
 183	 sleep 3
 184	
 185	 # 检查进程是否启动
 186	 if pgrep -f 'com.github.kirer.adb.Launcher' > /dev/null; then
 187	 echo "KServer进程启动成功"
 188	 else
 189	 echo "KServer进程启动失败"
 190	 fi
 191	
 192	 # 检查端口是否监听
 193	 if netstat -an | grep ":$port.*LISTEN" > /dev/null; then
 194	 echo "Socket服务器监听端口${port}成功"
 195	 else
 196	 echo "Socket服务器监听端口${port}失败"
 197	 fi
 198	 """.trimIndent()
 199	 }
 200	
 201	 /**
 202	 * 检查KServer进程是否运行
 203	 */
 204	 private suspend fun checkKServerProcess(shizukuManager: ShizukuManager): Boolean {
 205	 // 检查进程
 206	 val processResult = shizukuManager.executeShellCommand("pgrep -f 'com.github.kirer.adb.Launcher'")
 207	 val processRunning = processResult.success && processResult.output.trim().isNotEmpty()
 208	
 209	 // 检查端口监听
 210	 val portResult = shizukuManager.executeShellCommand("netstat -an | grep ':$DEFAULT_PORT.*LISTEN'")
 211	 val portListening = portResult.success && portResult.output.trim().isNotEmpty()
 212	
 213	 Log.d(TAG, "进程检查: 进程运行=$processRunning, 端口监听=$portListening")
 214	 Log.d(TAG, "进程输出: ${processResult.output}")
 215	 Log.d(TAG, "端口输出: ${portResult.output}")
 216	
 217	 // 如果进程存在但端口没有监听，说明进程僵死，需要重启
 218	 if (processRunning && !portListening) {
 219	 Log.w(TAG, "检测到僵死进程，尝试清理...")
 220	 cleanupZombieProcess(shizukuManager)
 221	 return false
 222	 }
 223	
 224	 return processRunning && portListening
 225	 }
 226	
 227	 /**
 228	 * 清理僵死进程
 229	 */
 230	 private suspend fun cleanupZombieProcess(shizukuManager: ShizukuManager) {
 231	 try {
 232	 val killResult = shizukuManager.executeShellCommand("pkill -f 'com.github.kirer.adb.Launcher'")
 233	 Log.d(TAG, "清理僵死进程结果: ${killResult.success}")
 234	 // 等待进程完全停止
 235	 delay(2000)
 236	 } catch (e: Exception) {
 237	 Log.e(TAG, "清理僵死进程失败", e)
 238	 }
 239	 }
