 244	 fun startHealthCheck() {
 245	 if (isHealthCheckEnabled) return
 246	
 247	 isHealthCheckEnabled = true
 248	 healthCheckJob = CoroutineScope(Dispatchers.IO).launch {
 249	 while (isHealthCheckEnabled) {
 250	 try {
 251	 delay(HEALTH_CHECK_INTERVAL)
 252	
 253	 if (isServiceRunning) {
 254	 val isActuallyRunning = checkKServerProcess(this@KServerManager.shizukuManager)
 255	 val canConnect = if (isActuallyRunning) testKServerConnection() else false
 256	
 257	 if (!isActuallyRunning || !canConnect) {
 258	 Log.w(TAG, "健康检查失败，KServer已停止，尝试自动重启...")
 259	
 260	 // 自动重启
 261	 val restartSuccess = startKServer()
 262	 if (restartSuccess) {
 263	 Log.i(TAG, "KServer自动重启成功")
 264	 } else {
 265	 Log.e(TAG, "KServer自动重启失败")
 266	 isServiceRunning = false
 267	 }
 268	 } else {
 269	 Log.d(TAG, "健康检查通过")
 270	 }
 271	 }
 272	 } catch (e: Exception) {
 273	 Log.e(TAG, "健康检查异常", e)
 274	 }
 275	 }
 276	 }
 277	
 278	 Log.d(TAG, "健康检查已启动")
 279	 }
