 74	 /**
 75	 * 解析命令行参数
 76	 */
 77	 private static ScreenshotConfig parseArguments(String[] args) {
 78	 ScreenshotConfig config = new ScreenshotConfig();
 79	 for (int i = 0; i < args.length; i++) {
 80	 String arg = args[i];
 81	 try {
 82	 switch (arg) {
 83	 case "--help":
 84	 case "-h":
 85	 printUsage();
 86	 System.exit(0);
 87	 break;
 88	 case "--version":
 89	 case "-v":
 90	 System.out.println("Screenshot Service v" + VERSION);
 91	 System.exit(0);
 92	 break;
 93	 case "--debug":
 94	 Ln.initLogLevel(Ln.Level.DEBUG);
 95	 break;
 96	 case "--port":
 97	 case "-p":
 98	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 99	 socketPort = Integer.parseInt(args[++i]);
 100	 }
 101	 break;
 102	 case "--display-id":
 103	 case "-d":
 104	 if (i + 1 < args.length) {
 105	 config.setDisplayId(Integer.parseInt(args[++i]));
 106	 }
 107	 break;
 108	 case "--max-images":
 109	 case "-m":
 110	 if (i + 1 < args.length) {
 111	 config.setMaxImages(Integer.parseInt(args[++i]));
 112	 }
 113	 break;
 114	 case "--no-auto-rotate":
 115	 config.setAutoRotate(false);
 116	 break;
 117	 case "--socket":
 118	 case "-s":
 119	 socketMode = true;
 120	 break;
 121	 default:
 122	 if (arg.startsWith("-")) {
 123	 Ln.w("Unknown argument: " + arg);
 124	 } else {
 125	 // 非选项参数作为直接命令
 126	 if (directCommand == null) {
 127	 directCommand = arg;
 128	 } else {
 129	 directCommand += " " + arg;
 130	 }
 131	 }
 132	 break;
 133	 }
 134	 } catch (NumberFormatException e) {
 135	 Ln.e("Invalid number format for argument " + arg);
 136	 System.exit(1);
 137	 }
 138	 }
 139	
 140	 Ln.i("Using config: " + config);
 141	 if (socketMode) {
 142	 Ln.i("Socket mode enabled on port: " + socketPort);
 143	 } else {
 144	 Ln.i("Direct mode enabled with command: " + (directCommand != null ? directCommand : "none"));
 145	 }
 146	
 147	 return config;
 148	 }
