 230	 /**
 231	 * 将字节数组写入Ashmem缓冲区
 232	 */
 233	 public static boolean writeToBuffer(AshmemBuffer buffer, byte[] data, int offset, int length) {
 234	 if (buffer == null || buffer.isClosed()) {
 235	 return false;
 236	 }
 237	 
 238	 if (data == null || offset < 0 || length < 0 || offset + length > data.length) {
 239	 return false;
 240	 }
 241	 
 242	 if (length > buffer.getSize()) {
 243	 Ln.w("数据长度超过缓冲区大小: " + length + " > " + buffer.getSize());
 244	 return false;
 245	 }
 246	 
 247	 try {
 248	 ByteBuffer byteBuffer = buffer.getBuffer();
 249	 byteBuffer.clear();
 250	 byteBuffer.put(data, offset, length);
 251	 byteBuffer.flip();
 252	 return true;
 253	 } catch (Exception e) {
 254	 Ln.e("写入AshmemBuffer失败", e);
 255	 return false;
 256	 }
 257	 }
 258	 
 259	 /**
 260	 * 从Ashmem缓冲区读取字节数组
 261	 */
 262	 public static byte[] readFromBuffer(AshmemBuffer buffer, int length) {
 263	 if (buffer == null || buffer.isClosed()) {
 264	 return null;
 265	 }
 266	 
 267	 if (length <= 0 || length > buffer.getSize()) {
 268	 return null;
 269	 }
 270	 
 271	 try {
 272	 ByteBuffer byteBuffer = buffer.getBuffer();
 273	 byte[] data = new byte[length];
 274	 byteBuffer.rewind();
 275	 byteBuffer.get(data, 0, length);
 276	 return data;
 277	 } catch (Exception e) {
 278	 Ln.e("从AshmemBuffer读取失败", e);
 279	 return null;
 280	 }
 281	 }
 282	}
