 242	 /**
 243	 * 将Image转换为Bitmap
 244	 */
 245	 private Bitmap convertImageToBitmap(Image image) {
 246	 try {
 247	 Image.Plane[] planes = image.getPlanes();
 248	 if (planes.length == 0) {
 249	 return null;
 250	 }
 251	
 252	 Image.Plane plane = planes[0];
 253	 ByteBuffer buffer = plane.getBuffer();
 254	 int width = image.getWidth();
 255	 int height = image.getHeight();
 256	 int pixelStride = plane.getPixelStride();
 257	 int rowStride = plane.getRowStride();
 258	 int rowPadding = rowStride - pixelStride * width;
 259	
 260	 Bitmap bitmap = Bitmap.createBitmap(width + rowPadding / pixelStride, height, Bitmap.Config.ARGB_8888);
 261	 bitmap.copyPixelsFromBuffer(buffer);
 262	
 263	 if (rowPadding != 0) {
 264	 bitmap = Bitmap.createBitmap(bitmap, 0, 0, width, height);
 265	 }
 266	
 267	 return bitmap;
 268	 } catch (Exception e) {
 269	 Ln.e("转换Image为Bitmap失败", e);
 270	 return null;
 271	 }
 272	 }
