 52	 public void initialize() throws Exception {
 53	 Ln.i("Initializing ScreenCaptureManager...");
 54	 try {
 55	 // 获取DisplayManager
 56	 displayManager = ServiceManager.getDisplayManager();
 57	 if (displayManager == null) {
 58	 throw new Exception("Failed to get DisplayManager");
 59	 }
 60	 // 获取显示器信息
 61	 displayInfo = displayManager.getDisplayInfo(displayId);
 62	 if (displayInfo == null) {
 63	 throw new Exception("Display " + displayId + " not found");
 64	 }
 65	 Ln.i("Display info: " + displayInfo.getSize().getWidth() + "x" + displayInfo.getSize().getHeight() + ", rotation=" + displayInfo.getRotation() + ", dpi=" + displayInfo.getDpi());
 66	 // 创建ImageReaderHandler
 67	 imageReaderHandler = new ImageReaderHandler(config);
 68	 initialized = true;
 69	 Ln.i("ScreenCaptureManager initialized successfully");
 70	 } catch (Exception e) {
 71	 Ln.e("Failed to initialize ScreenCaptureManager", e);
 72	 cleanup();
 73	 throw e;
 74	 }
 75	 }
