 95	 /**
 96	 * 创建镜像VirtualDisplay
 97	 *
 98	 */
 99	 private void createVirtualDisplay() {
 100	 if (displayInfo == null) {
 101	 throw new IllegalStateException("Display info not available");
 102	 }
 103	 if (imageReaderHandler == null || !imageReaderHandler.isCreated()) {
 104	 throw new IllegalStateException("ImageReader not created");
 105	 }
 106	 int width = displayInfo.getSize().getWidth();
 107	 int height = displayInfo.getSize().getHeight();
 108	 Size inputSize = new Size(width, height);
 109	 Ln.i("Creating VirtualDisplay: " + width + "x" + height + " for display " + displayId);
 110	 try {
 111	 virtualDisplay = displayManager.createVirtualDisplay(
 112	 "scrcpy",
 113	 inputSize.getWidth(),
 114	 inputSize.getHeight(),
 115	 displayId, // 镜像现有显示器
 116	 imageReaderHandler.getSurface()
 117	 );
 118	 Ln.d("Display: using DisplayManager API:" + virtualDisplay.getDisplay().getDisplayId());
 119	 } catch (Exception displayManagerException) {
 120	 Ln.w("DisplayManager createVirtualDisplay failed, trying SurfaceControl API");
 121	 try {
 122	 // 降级方案
 123	 IBinder display = createDisplay();
 124	 Size deviceSize = displayInfo.getSize();
 125	 int layerStack = displayInfo.getLayerStack();
 126	 setDisplaySurface(display, imageReaderHandler.getSurface(), deviceSize.toRect(), inputSize.toRect(), layerStack);
 127	 Ln.d("Display: using SurfaceControl API");
 128	 } catch (Exception surfaceControlException) {
 129	 Ln.e("Could not create display using DisplayManager", displayManagerException);
 130	 Ln.e("Could not create display using SurfaceControl", surfaceControlException);
 131	 throw new AssertionError("Could not create display");
 132	 }
 133	 }
 134	 }
