 156	 /**
 157	 * 降级方案 创建显示
 158	 */
 159	 private static IBinder createDisplay() throws Exception {
 160	 // Since Android 12 (preview), secure displays could not be created with shell permissions anymore.
 161	 // On Android 12 preview, SDK_INT is still R (not S), but CODENAME is "S".
 162	 boolean secure = Build.VERSION.SDK_INT < AndroidVersions.API_30_ANDROID_11 || (Build.VERSION.SDK_INT == AndroidVersions.API_30_ANDROID_11
 163	 && !"S".equals(Build.VERSION.CODENAME));
 164	 return SurfaceControl.createDisplay("scrcpy", secure);
 165	 }
