 253	 int rotationAngle = BitmapConverter.getRotationAngle(displayInfo.getRotation());
 254	 if (rotationAngle != 0) {
 255	 bitmap = BitmapConverter.rotateBitmap(bitmap, rotationAngle);
 256	 }
