 359	 "raw" -> client.takeScreenshotOptimized("raw", 100)
 360	 else -> client.takeScreenshotPng()
 361	 }
 362	
 363	 if (response.success && response.data != null) {
 364	 Log.d(TAG, "截图成功，大小: ${response.data.size} bytes")
 365	 response.data
 366	 } else {
 367	 Log.w(TAG, "截图失败: ${response.message}")
 368	 null
 369	 }
 370	
 371	 } catch (e: Exception) {
 372	 Log.e(TAG, "截图测试失败", e)
 373	 null
