 11	
 12	/**
 13	 * 简化的图像处理器
 14	 * 只支持RAW格式和零拷贝传输
 15	 */
 16	public class ImageProcessor {
 17	 // 处理结果
 18	 public static class ProcessResult {
 19	 public final AshmemManager.AshmemBuffer buffer;
 20	 public final int dataSize;
 21	 public final int width;
 22	 public final int height;
