 34	 private final BufferPool bufferPool;
 35	 private final AtomicLong totalProcessed = new AtomicLong(0);
 36	 private final AtomicLong totalProcessingTime = new AtomicLong(0);
 37	
 38	 /**
 39	 * 创建图像处理器
 40	 *
 41	 * @param maxBufferSize 最大缓冲区大小
 42	 * @param poolSize 缓冲池大小
 43	 */
 44	 public ImageProcessor(int maxBufferSize, int poolSize) {
 45	 this.bufferPool = new BufferPool("ImageProcessor", maxBufferSize, poolSize / 2, poolSize);
 46	 Ln.i("OptimizedImageProcessor创建成功，maxBufferSize=" + maxBufferSize + ", poolSize=" + poolSize);
 47	 }
 48	
 49	 /**
 50	 * 处理Image对象
 51	 *
 52	 * @param image 输入图像
 53	 * @return 处理结果，失败时返回null
 54	 */
 55	 public ProcessResult processImage(Image image) {
 56	 if (image == null) {
 57	 return null;
 58	 }
 59	 long startTime = System.currentTimeMillis();
 60	 try {
 61	 try {
 62	 int width = image.getWidth();
 63	 int height = image.getHeight();
 64	 // 获取像素数据
 65	 Image.Plane[] planes = image.getPlanes();
 66	 if (planes.length == 0) {
 67	 Ln.e("Image没有planes");
 68	 return null;
 69	 }
 70	 Image.Plane plane = planes[0];
 71	 ByteBuffer buffer = plane.getBuffer();
 72	 int pixelStride = plane.getPixelStride();
 73	 int rowStride = plane.getRowStride();
 74	 int rowPadding = rowStride - pixelStride * width;
 75	 // 计算实际数据大小
 76	 int dataSize = width * height * 4; // RGBA = 4 bytes per pixel
 77	 // 从缓冲池获取缓冲区
 78	 AshmemManager.AshmemBuffer ashmemBuffer = bufferPool.acquire();
 79	 if (ashmemBuffer == null) {
 80	 Ln.e("无法获取缓冲区");
 81	 return null;
 82	 }
 83	 // 检查缓冲区大小
 84	 if (dataSize > ashmemBuffer.getSize()) {
 85	 Ln.e("数据大小超过缓冲区: " + dataSize + " > " + ashmemBuffer.getSize());
 86	 bufferPool.release(ashmemBuffer);
 87	 return null;
 88	 }
 89	 // 复制像素数据到Ashmem缓冲区
 90	 ByteBuffer targetBuffer = ashmemBuffer.getBuffer();
 91	 targetBuffer.clear();
 92	 if (rowPadding == 0) {
 93	 // 没有padding，直接复制
 94	 targetBuffer.put(buffer);
 95	 } else {
 96	 // 有padding，逐行复制
 97	 buffer.rewind();
 98	 for (int row = 0; row < height; row++) {
 99	 for (int col = 0; col < width; col++) {
 100	 // 复制RGBA像素
 101	 for (int component = 0; component < pixelStride; component++) {
 102	 targetBuffer.put(buffer.get());
 103	 }
 104	 }
 105	 // 跳过padding
 106	 buffer.position(buffer.position() + rowPadding);
 107	 }
 108	 }
 109	 targetBuffer.flip();
 110	 long processingTime = System.currentTimeMillis() - startTime;
 111	 Ln.d("原始处理完成: " + width + "x" + height + ", " + dataSize + " bytes, " + processingTime + "ms");
 112	 return new ProcessResult(ashmemBuffer, dataSize, width, height, processingTime);
 113	 } catch (Exception e) {
 114	 Ln.e("处理原始RGBA失败", e);
 115	 return null;
 116	 }
 117	 } catch (Exception e) {
 118	 Ln.e("处理图像失败", e);
 119	 return null;
 120	 } finally {
 121	 long processingTime = System.currentTimeMillis() - startTime;
 122	 totalProcessed.incrementAndGet();
 123	 totalProcessingTime.addAndGet(processingTime);
 124	 }
 125	 }
 126	}
