 31	 */
 32	 public String processCommand(String request) {
 33	 CommandResult result = execute(request);
 34	 return result.toStringResponse();
 35	 }
 36	
 37	 /**
 38	 * 处理命令请求并返回结果对象
 39	 */
 40	 public CommandResult execute(String request) {
 41	 if (request == null || request.trim().isEmpty()) {
 42	 return CommandResult.error("Empty command");
 43	 }
 44	
 45	 try {
 46	 String[] parts = request.trim().split("\\s+");
 47	 String commandName = parts[0].toLowerCase();
 48	 String[] params = new String[parts.length - 1];
 49	 System.arraycopy(parts, 1, params, 0, params.length);
 50	
 51	 Ln.d("Processing command: " + commandName);
 52	
 53	 // 内置命令
 54	 if ("help".equals(commandName)) {
 55	 return CommandResult.success(handleHelpCommand().substring(3)); // 移除 "OK " 前缀
 56	 }
 57	
 58	 if ("status".equals(commandName)) {
 59	 return CommandResult.success("Service running with " + commands.size() + " commands");
 60	 }
 61	
 62	 // 查找并执行注册的命令
 63	 ServiceCommand command = commands.get(commandName);
 64	 if (command == null) {
 65	 return CommandResult.error("Unknown command: " + commandName);
 66	 }
 67	
 68	 // 执行命令
 69	 return command.execute(params);
 70	
 71	 } catch (Exception e) {
 72	 Ln.e("Error processing command: " + request, e);
 73	 return CommandResult.error(e.getMessage());
 74	 }
 75	 }
 76	 
 77	 private String handleHelpCommand() {
 78	 StringBuilder sb = new StringBuilder("Available commands:\n");
 79	 sb.append(" help - Show this help\n");
 80	 sb.append(" status - Show service status\n");
 81	 
 82	 for (ServiceCommand command : commands.values()) {
 83	 sb.append(" ").append(command.getCommandName())
 84	 .append(" - ").append(command.getHelp()).append("\n");
 85	 }
 86	 
 87	 return "OK " + sb.toString();
 88	 }
 89	}
