 68	 val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
 69	 view.setPadding(
 70	 systemBars.left + 16,
 71	 systemBars.top + 16,
 72	 systemBars.right + 16,
 73	 systemBars.bottom + 16
 74	 )
 75	 insets
 76	 }
 77	 setupUI()
 78	 setupObservers()
