 104	 private fun startTitleCounter() {
 105	 titleUpdateHandler = Handler(Looper.getMainLooper())
 106	 titleUpdateRunnable = object : Runnable {
 107	 override fun run() {
 108	 titleCounter++
 109	 title = "KServer Client - $titleCounter"
 110	 titleUpdateHandler?.postDelayed(this, 1000) // 每秒更新一次
 111	 }
 112	 }
 113	 titleUpdateRunnable?.let { titleUpdateHandler?.post(it) }
 114	 }
 115	
 116	 /**
 117	 * 停止标题计数器
 118	 */
 119	 private fun stopTitleCounter() {
 120	 titleUpdateRunnable?.let { titleUpdateHandler?.removeCallbacks(it) }
 121	 titleUpdateHandler = null
 122	 titleUpdateRunnable = null
 123	 }
