 416	 @SuppressLint("UseKtx", "SetTextI18n")
 417	 private fun displayScreenshot(data: ByteArray, size: Int) {
 418	 try {
 419	 // RAW格式需要特殊处理 - 动态获取屏幕分辨率
 420	 val displayMetrics = resources.displayMetrics
 421	 val width = displayMetrics.widthPixels
 422	 val height = displayMetrics.heightPixels
 423	 val expectedSize = width * height * 4 // RGBA = 4 bytes per pixel
 424	 addLog("屏幕分辨率: ${width}x${height}, 期望数据大小: $expectedSize, 实际数据大小: ${data.size}")
 425	 // 创建Bitmap并设置像素数据
 426	 val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
 427	 val buffer = java.nio.ByteBuffer.wrap(data)
 428	 bitmap.copyPixelsFromBuffer(buffer)
 429	 binding.ivScreenshot.setImageBitmap(bitmap)
 430	 val sizeText = formatFileSize(size)
 431	 binding.tvImageInfo.text = "大小: $sizeText, 分辨率: ${width}x${height}"
 432	 addLog("RAW截图显示成功: ${width}x${height}, $sizeText")
 433	 } catch (e: Exception) {
 434	 addLog("显示截图时出错: ${e.message}")
 435	 }
 436	 }
 437	 
 438	 private fun addLog(message: String) {
 439	 val timestamp = SimpleDateFormat("HH:mm:ss", Locale.getDefault()).format(Date())
 440	 viewModel.addLog("[$timestamp] $message")
 441	 }
 442	 
 443	 private fun showToast(message: String) {
 444	 Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
 445	 }
 446	 
 447	 private fun formatFileSize(bytes: Int): String {
 448	 return when {
 449	 bytes < 1024 -> "$bytes B"
 450	 bytes < 1024 * 1024 -> "${bytes / 1024} KB"
 451	 else -> "${bytes / (1024 * 1024)} MB"
 452	 }
 453	 }
 454	
